 </div>
 </div>
 </details>
 </div>
</div>
</details>

<style>
.status-bar details {
 margin-bottom: 0;
 max-width: 350px; 
}
.status-bar summary {
 cursor: pointer;
 background: linear-gradient(90deg, #c2576d, #8e5cc0);
 padding: 10px 15px;
 border-radius: 10px 10px 0 0;
 color: #f0f0f0;
 font-weight: bold;
}
.summary-icon {
 margin-right: 8px;
}
.status-content {
 background: #1e1e2e;
 color: #f0f0f0;
 border-radius: 0 0 10px 10px;
 overflow: hidden;
 font-family: Arial, sans-serif;
}
.module-section {
 padding: 15px;
 border-bottom: 1px solid #333;
}
.module-section:last-child {
 border-bottom: none; 
}
.char-name {
 font-weight: bold;
 font-size: 16px;
 color: #ffc0cb;
 margin-bottom: 8px;
}
.name-highlight {
 background-color: #ee66ee;
 color: white;
 padding: 2px 5px;
 border-radius: 3px;
 line-height: 1.5;
}
.info-grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 8px 5px;
 font-size: 12px;
 color: #d0d0e0;
}
.info-full-span {
 grid-column: 1 / -1;
}
.info-value-highlight {
 color: #ffffff;
}
.info-type-highlight {
 color: #ffb3ff;
 font-weight: bold;
}
.lock-label {
 font-size: 12px;
 color: #ce93d8;
 margin-top: 10px;
 margin-bottom: 4px;
}
.lock-label:first-of-type {
 margin-top: 15px;
}
.lock-status-box {
 font-size: 12px;
 color: #e0e0e0;
 background: #2d2d44;
 padding: 6px 10px;
 border-radius: 4px;
}
.progress-label.outfit {
 font-size: 12px;
 margin-bottom: 4px;
}
.nested-summary {
 cursor: pointer;
 font-size: 12px;
}
.nested-content-grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 8px;
 font-size: 12px;
 padding: 10px;
 background: #2d2d44; 
 border-radius: 4px;
}
.nested-content-grid.occult {
 font-style: italic;
}
.nested-title {
 color: #ffb3ff; 
}
.nested-title.occult {
 color: #ffcc80; 
}
.nested-value {
 color: #e0e0e0;
}
.nested-summary.outfit {
 color: #a5d6a7;
}
.nested-summary.occult {
 color: #ffcc80;
}
/* 玄沧提供的进度条样式 */
.probability-item {
 display: flex;
 align-items: center;
 margin: 10px 0;
}
.probability-label {
 font-weight: bold;
 font-size: 0.9em;
 min-width: 65px;
 flex-shrink: 0;
 color: #ee66ee;
}
.prob-bar-wrapper {
 position: relative;
 height: 15px;
 border-radius: 8px;
 overflow: hidden;
 background-color: rgba(255, 255, 255, 0.1); 
 flex-grow: 1;
}
.prob-bar {
 position: absolute;
 top: 0;
 left: 0;
 height: 100%;
 width: 100%;
 border: none;
}
.prob-bar::-webkit-progress-bar {
 background: transparent;
}
.prob-bar::-webkit-progress-value {
 background: linear-gradient(to right, #ffab91, #e91e63);
 border-radius: 8px;
}
.prob-value {
 position: absolute;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 color: #fff;
 font-size: 10px;
 font-weight: bold;
 text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
}
</style>

